			nei, w := edge[0], edge[1]
			dfs(nei, time+w)
		}
	}

	dfs(k, 0)
	res := 0
	for _, time := range dist {
		if time == math.MaxInt32 {
			return -1
		}
		if time > res {
			res = time
		}
	}
	return res
