        dist[k - 1] = 0

        for _ in 0..<n - 1 {
            var updated = false
            for time in times {
                let u = time[0] - 1, v = time[1] - 1, w = time[2]
                if dist[u] != Int.max && dist[u] + w < dist[v] {
                    dist[v] = dist[u] + w
                    updated = true
                }
            }
            if !updated {
                break
            }
        }

        let maxDist = dist.max()!
        return maxDist == Int.max ? -1 : maxDist
    }
